const PHONE_COUNTRY_NAMES=new Intl.DisplayNames(['ru'],{type:'region'});
const PHONE_COUNTRIES=getCountries().map(code=>[code,PHONE_COUNTRY_NAMES.of(code)||code,getCountryCallingCode(code),15] as const).sort((a,b)=>a[1].localeCompare(b[1],'ru'));
function countryForPhone(value:string){return parsePhoneNumberFromString(String(value??''))?.country??'RU'}
function formatPhoneForCountry(value:string,country:string,forceCountry=false){const entry=PHONE_COUNTRIES.find(x=>x[0]===country)??PHONE_COUNTRIES.find(x=>x[0]==='RU')!;const raw=String(value??'').trim();if(!raw)return '';const parsed=parsePhoneNumberFromString(raw);if(country==='RU'&&(forceCountry||!parsed?.country||parsed.country==='RU'))return formatRussianPhoneInput(raw);if(parsed?.country&&!forceCountry)return parsed.formatInternational();let digits=parsed?.nationalNumber??raw.replace(/\D/g,'');if(!parsed&&raw.startsWith('+')){const current=[...PHONE_COUNTRIES].sort((a,b)=>b[2].length-a[2].length).find(x=>digits.startsWith(x[2]));if(current)digits=digits.slice(current[2].length)}else if(!parsed&&digits.startsWith(entry[2]))digits=digits.slice(entry[2].length);digits=digits.slice(0,15);const national=new AsYouType(country as CountryCode).input(digits);return '+'+entry[2]+(national?' '+national:'')}

